    total = 0.0
    with open('input.csv', newline='', encoding='utf-8') as fh:
        for row in csv.DictReader(fh):
            value = row.get('amount', '').strip()
            if value:
                total += float(value)
    print(f'Revenue: {total:.2f}')

if __name__ == '__main__':
    main()

